import e from"./DumpStrategy.mjs";var t=class extends e{static id=`dump_postgres`;static label=`Dump Postgres`;static description=`This strategy uses pg_dump to backup a Postgres database.`;constructor(e){super(e),this.backup_filename=`database.sql`,this.docker_image=this.config.docker_image||`postgres:latest`,this.docker_env={PGPASSWORD:this.config.postgres_password||``};let t=[`--host=${this.config.postgres_host||`localhost`}`,`--port=${this.config.postgres_port||5432}`,`--username=${this.config.postgres_username||`postgres`}`,`--dbname=${this.config.postgres_database||`postgres`}`];this.backup_command=`pg_dump ${t.join(` `)} --file={{output}} --clean`,this.restore_command=`psql ${t.join(` `)} -f {{input}}`}};export{t as default};